using System.Collections.Generic;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CreateAnomalyAction", menuName = "Data/Battle/Battle Actions/Enemy/CreateAnomaly Action")]
public class CreateAnomalyAction : BattleAction
{
	[Header("Create Anomaly")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private ListCorruptedAnimalDataEvent OnSpawnMinions;

	[SerializeField]
	private GameObjectEvent OnSpawnMinionVFX;

	public override void Cast(GameObject source)
	{
		List<CorruptedAnimalData> list = new List<CorruptedAnimalData>();
		CorruptedAnimalData corruptedAnimalData = currentCorruptedAnimals.GetCorruptionSource().GetComponent<CorruptedAnimalCorruptionStats>().CorruptedAnimalData;
		for (int i = 0; i < corruptedAnimalData.Minions.Count; i++)
		{
			for (int j = 0; j < corruptedAnimalData.Minions[i].MinionAmount; j++)
			{
				list.Add(corruptedAnimalData.Minions[i].MinionData);
			}
		}
		if (IsVFXEnabled())
		{
			OnSpawnMinionVFX.Raise(base.BaseBattleActionData.VfxPrefab);
		}
		OnSpawnMinions.Raise(list);
	}
}
